    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();

    const [hasSizeRequiredError, setHasSizeRequiredError] = useState(false);

    const isSelectedSizeOOS = (() => {
      const sizeAttr = product?.variationAttributes?.find((a: SfccProduct) => a.id === SFCC_SIZE_ATTRIBUTE_ID);
      const selectedSize = effectiveSizeValue;
      if (!selectedSize || !sizeAttr) return false;
      return sizeAttr.values?.find((v: SfccProduct) => v.value === selectedSize)?.orderable === false;
    })();

    const isMaxOrderQtyReached = useMemo(() => {
      if (maxOrderQuantity == null) return false;
      const productId = variant?.productId;
      if (!productId) return false;
      const inBag = basketProductItems
        .filter((item) => item.productId === productId)
        .reduce((sum, item) => sum + (item.quantity ?? 0), 0);
      return inBag >= maxOrderQuantity;
    }, [maxOrderQuantity, basketProductItems, variant]);

    const handleAddToBag = async () => {
      // aria-disabled keeps the button clickable for screen-reader announcement, so re-check
      // the hard-blocking states before doing any work.
      if (isSelectedSizeOOS || isMaxOrderQtyReached) return;
      // Only gate on size selection when the product actually has a size attribute.
      // Colour-only and simple products must not be blocked by this check.
      if (hasSizeAttribute && !effectiveSizeValue) {
        setHasSizeRequiredError(true);
        // A4 — move focus back to the size selector trigger so keyboard users know where to act.
        // Timeout of 0 lets React flush the error state update before the focus call.
        setTimeout(() => sizeSelectorRef.current?.focusTrigger(), 0);
        return;
      }
      setHasSizeRequiredError(false);

      // Delegate to the full validation + cart mutation + modal flow.
      const hasValidSelection = validateAndShowError();
      if (!hasValidSelection || !addToCart) return;
      try {
        const itemsAdded = await addToCart([{ product, variant, quantity }]);
        if (itemsAdded) {
          // See addToBagTriggerRef's own comment above for why a DOM query, not a ref/event
          // passed through ZimmButton, is how the trigger element is obtained here.
          const trigger = addToBagTriggerRef.current?.querySelector<HTMLButtonElement>('button');
          onCartDrawerOpen(trigger);
        }
      } catch {
        showToast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' });
      }
    };

    const { disableButton, customInventoryMessage } = useMemo(() => {
      let shouldDisableButton = showInventoryMessage;
      let currentInventoryMsg = '';
      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
        // if any of the children are not orderable, it will disable the add to cart button
        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
          return childProductOrderability[key].showInventoryMessage;
